// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate KS state additions
            double additions = 0.0;

            // KS requires addback of:
            // - Federal interest income (taxable to KS)
            // - State income tax refunds included in federal income
            // - IRC 163(j) business interest expense carryforward deductions
            // - State income taxes deducted federally

            // Example additions (would be calculated from entity fields):
            // additions += revenue.federal_bond_interest;
            // additions += result.state_tax_refunds;
            // additions += result.irc_163j_adjustments;
            // additions += result.state_taxes_deducted;

            apportionment.state_additions = additions;

            // Calculate KS state subtractions
            double subtractions = 0.0;

            // KS allows subtraction of:
            // - Kansas municipal bond interest (exempt for KS purposes)
            // - Kansas net operating loss deduction (if applicable)
            // - State income taxes paid during the year

            // Example subtractions (would be calculated from entity fields):
            // subtractions += revenue.ks_municipal_interest;
            // subtractions += result.ks_nol_deduction;
            // subtractions += result.state_taxes_paid;

            apportionment.state_subtractions = subtractions;

            // Split income at surtax threshold
            result.ks_income_below_threshold = apportionment.surtax_threshold;
            result.ks_income_above_threshold =
              apportionment.state_taxable_income - apportionment.surtax_threshold;

            // Calculate base tax at 4.0% on ALL income
            result.ks_base_tax =
              apportionment.state_taxable_income * apportionment.state_tax_base_rate;

            // Calculate surtax at 3.0% on income ABOVE $50,000
            result.ks_surtax =
              result.ks_income_above_threshold * apportionment.state_tax_surtax_rate;

            // Total KS tax = base tax + surtax
            apportionment.state_tax = result.ks_base_tax + result.ks_surtax;

            // Subtract KS state credits
            // KS offers various credits: job creation, film production,
            // historic preservation, community service contribution, etc.
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // All income below threshold - no surtax
            result.ks_income_below_threshold = apportionment.state_taxable_income;
            result.ks_income_above_threshold = 0.0;

            // Calculate base tax at 4.0% only (no surtax)
            result.ks_base_tax =
              apportionment.state_taxable_income * apportionment.state_tax_base_rate;
            result.ks_surtax = 0.0;

            // Total KS tax = base tax only (no surtax)
            apportionment.state_tax = result.ks_base_tax;

            // Subtract KS state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

result.ks_income_below_threshold = 0.0;
result.ks_income_above_threshold = 0.0;
result.ks_base_tax = 0.0;
result.ks_surtax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

